import {RelationshipTypePicker} from '../../shared/RelationshipTypePicker.jsx';
import {relationName} from '../../shared/relation-color.mjs';
import React,{useState,useRef} from 'react';
import {Modal} from '../../shared/preferences.tsx';
import {useResource} from '../../shared/state.js';
import {useDialog} from '../../dialog.tsx';
import {useAutosizeTextarea} from '../../shared/useAutosizeTextarea.ts';
import {changeKey,proofReview} from '../../../domain/story-relation-edit.mjs';
import {relationPoint,relationTimeLabel,relationSnapshot,pair} from '../../../domain/story-relations.mjs';
import {relationEditStyle} from './relation-edit-style.mjs';

const describe=(p,chapters)=>[p.location?.narration&&(chapters.find(c=>c.id===p.location.narration.chapterId)?.title||'章节已移除')+' · '+Math.round(p.location.narration.offset*100)+'%',p.location?.story?.binding?.kind==='card'?'跟随剧情卡 · '+(p.location.story.binding.offset||0)+' 天':Number.isFinite(p.location?.story)?'旧坐标（固定） '+p.location.story:null].filter(Boolean).join(' / ')||'时间待定';
export const changeSource=(card,point,r,index)=>({cardId:card.id,revision:card.revision,pointId:point.id,changeId:changeKey(r,index)});

export function RelationPointManager({call,novelId,state,sources,people,relations=[],cardId,save,unavailable,close}){
 const [editing,setEditing]=useState(null),{confirm}=useDialog();
 const card=state.cards[cardId],characters=people.filter(p=>p.type==='character_card'),name=id=>characters.find(p=>p.id===id)?.name||'人物已删除',typeName=r=>sources.relationshipTypes?.find(t=>t.id===r.typeId)?.name||r.name;
 if(editing)return <RelationChangeEditor {...{call,novelId,state,sources,characters,relations,save,unavailable}} selected={cardId} source={editing.source} defaultPointId={editing.pointId} close={()=>setEditing(null)}/>;
 return <Modal title="剧情卡 · 关系变化" close={close} className="re-dialog"><style>{relationEditStyle}</style><div className="re-manager"><header><div><small>剧情内的发生点</small><h3>{card?.title||'剧情卡已删除'}</h3></div><button disabled={unavailable||!card||characters.length<2||card.status==='dropped'} onClick={()=>setEditing({})}>＋ 添加变化</button></header>
  <p className="re-help">每个发生点可记录多次变化，按下方顺序依次生效。绑定点会跟随剧情卡的故事时间移动；旧坐标点保持固定。叙述位置与正文依据不会改变。</p>
  {!card?.points.some(p=>p.relationships?.length)&&<div className="re-empty">还没有关系变化。可以先记下计划，时间与正文依据稍后再补。</div>}
  {[...card?.points||[]].filter(p=>p.relationships?.length).sort((a,b)=>(relationPoint(a,'narration',sources.chapters)??Infinity)-(relationPoint(b,'narration',sources.chapters)??Infinity)||(a.order||0)-(b.order||0)).map(point=><section className="re-point" key={point.id}><header><strong>{describe(point,sources.chapters)}</strong><small>{point.relationships.length} 次变化</small></header>{point.relationships.map((r,index)=><div className="re-item" key={changeKey(r,index)}><span className="re-order">{String(index+1).padStart(2,'0')}</span><div className="re-item-content"><div className="re-item-meta"><small>{name(r.from)} <span>↔</span> {name(r.to)}</small><span className={'re-badge '+(r.evidence?'confirmed':'planned')}>{r.evidence?'正文已确认':'计划'}</span>{proofReview(r.evidence,sources.chapters)&&<span className="re-badge review">依据待复核</span>}</div><strong>{typeName(r)}</strong>{r.reason&&<p>{r.reason}</p>}</div><div className="re-item-actions"><button aria-label={'编辑关系变化 '+r.name} onClick={()=>setEditing({source:changeSource(card,point,r,index)})}>编辑</button><details className="re-item-menu"><summary aria-label={'更多操作 '+r.name} title="更多操作">⋯</summary><nav aria-label={r.name+'的操作'} onClick={e=>{if(e.target.closest('button'))e.currentTarget.closest('details').open=false;}}><button disabled={unavailable||index===0} aria-label={'上移变化 '+r.name} onClick={()=>save({type:'relation.order',source:changeSource(card,point,r,index),direction:'up'},'已调整同一发生点的变化顺序')}>↑ 上移</button><button disabled={unavailable||index===point.relationships.length-1} aria-label={'下移变化 '+r.name} onClick={()=>save({type:'relation.order',source:changeSource(card,point,r,index),direction:'down'},'已调整同一发生点的变化顺序')}>↓ 下移</button><button className="re-danger" aria-label={'删除关系变化 '+r.name} disabled={unavailable} onClick={async()=>{if(await confirm('删除这条关系变化及其引用依据？剧情卡、资料关系和正文会保留。'))await save({type:'relation.delete',source:changeSource(card,point,r,index)},'已删除关系变化，可通过规划撤销恢复');}}>删除变化</button></nav></details></div></div>)}<button className="re-add-at" disabled={unavailable||characters.length<2||card.status==='dropped'} onClick={()=>setEditing({pointId:point.id})}>＋ 在此点继续变化</button></section>)}
  <footer><button onClick={close}>返回剧情卡</button></footer>
 </div></Modal>;
}

export function RelationChangeEditor({call,novelId,state,sources,characters,relations=[],selected,source=null,defaultPointId='',mode='narration',origin=0,cursor=0,save,unavailable,close,initialPair=[]}){
 const {confirm}=useDialog(),cards=Object.values(state.cards).filter(c=>c.status!=='dropped'||c.id===source?.cardId);
 const [base]=useState(()=>structuredClone(state));
 const originalPoint=source?base.cards[source.cardId]?.points.find(p=>p.id===source.pointId):null;
 const original=originalPoint?.relationships.find((r,i)=>changeKey(r,i)===source.changeId);
 const [initial]=useState(()=>({cardId:source?.cardId||cards.find(c=>c.id===selected)?.id||cards[0]?.id||'',pointId:source?.pointId||defaultPointId,from:original?.from||initialPair[0]?.id||characters[0]?.id||'',to:original?.to||initialPair[1]?.id||characters[1]?.id||'',name:original?.name||'',typeId:original?.typeId??null,reason:original?.reason||'',location:structuredClone(originalPoint?.location||(state.storyAxis?{story:{binding:{kind:'card',offset:0}}}:{})),order:originalPoint?.order||0,fact:!!original?.evidence,chapterId:original?.evidence?.chapterId||'',quote:original?.evidence?.evidence||'',reconfirm:false}));
 const [value,setValue]=useState(initial),[error,setError]=useState(''),[saving,setSaving]=useState(false);
 const set=(key,next)=>setValue(v=>({...v,[key]:next})),card=base.cards[value.cardId],targetPoint=card?.points.find(p=>p.id===value.pointId),shared=targetPoint&&!(source?.cardId===value.cardId&&source?.pointId===value.pointId);
 const location=shared?targetPoint.location||{}:value.location;
 const proof=useResource(()=>value.fact&&value.chapterId?call('chapter.get',{novelId,chapterId:value.chapterId,maxChars:200000}):Promise.resolve(null),[call,novelId,value.fact,value.chapterId,sources.chapters.find(c=>c.id===value.chapterId)?.revision]);
 const current=proof.value?.id===value.chapterId?proof.value:null;
 
 const unchangedProof=original?.evidence&&!value.reconfirm&&value.from===original.from&&value.to===original.to&&value.name.trim()===original.name&&value.typeId===(original.typeId??null)&&value.reason.trim()===(original.reason||'')&&value.chapterId===original.evidence.chapterId&&value.quote===original.evidence.evidence;
 const validQuote=!!current&&!proof.loading&&!proof.error&&value.quote.trim()&&current.content.includes(value.quote);
 const hasLocation=location.narration&&sources.chapters.some(c=>c.id===location.narration.chapterId)||Number.isFinite(location.story)||location.story?.binding?.kind==='card';
 const invalid=!card||card.status==='dropped'||!value.name.trim()||value.from===value.to||!value.from||!value.to||value.fact&&(!hasLocation||!unchangedProof&&!validQuote);
 const dirty=JSON.stringify(value)!==JSON.stringify(initial),discard=async()=>{if(!saving&&(!dirty||await confirm('放弃本次未保存的关系修改？')))close();};
 const setLocation=(key,next)=>set('location',{...value.location,[key]:next});
 const useCursor=()=>{
  if(mode==='story'&&state.storyAxis){
   const time=card?.time?.story,coordinate=cursor+origin;
   if(time?.axisVersion!==1||!Number.isSafeInteger(coordinate)){setError('请先为剧情卡安排精确日期，再选取日期指针；折叠空白不能推算为发生日期。');return;}
   setLocation('story',{binding:{kind:'card',offset:coordinate-time.start}});return;
  }
  set('location',{...value.location,...(mode==='narration'?{narration:sources.chapters[Math.floor(cursor+origin)]?{chapterId:sources.chapters[Math.floor(cursor+origin)].id,offset:(cursor+origin)%1}:null}:{story:cursor+origin})});
 };
 const position=relationPoint({location},mode,sources.chapters,card,{storyAxis:state.storyAxis}),reference=position===null?null:relationSnapshot(state.cards,relations,sources.chapters,mode,position,true,{storyAxis:state.storyAxis,relationshipTypes:sources.relationshipTypes}).relations.find(r=>pair(r.from,r.to)===pair(value.from,value.to));
 const submit=async e=>{e.preventDefault();if(invalid||saving)return;setSaving(true);setError('');const evidence=value.fact?(unchangedProof?original.evidence:{chapterId:value.chapterId,revision:current?.revision,evidence:value.quote}):null;
  try{if(await save({type:'relation.save',source,cardId:value.cardId,expectedRevision:card.revision,pointId:value.pointId,location,order:value.order,value:{from:value.from,to:value.to,name:value.name,typeId:value.typeId,reason:value.reason,evidence},confirmed:value.fact},value.fact?'已保存正文确认的关系变化':'已保存关系计划'))close();else setError('保存未成功，填写内容已保留。剧情卡或正文可能已有更新，请关闭后重新打开核对。');}finally{setSaving(false);}
 };
 return <Modal title={source?'编辑关系变化':'添加关系变化'} close={discard} className="re-dialog"><style>{relationEditStyle}</style><form className="u-form re-form" onSubmit={submit}>
  <section className="re-section"><h4>01 <span>人物与变化</span></h4><div className="u-form-grid">{[['from','人物一'],['to','人物二']].map(([key,label])=><label key={key}>{label}<select aria-label={label} value={value[key]} onChange={e=>set(key,e.target.value)}><option value="">选择人物</option>{characters.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></label>)}</div>{reference&&<p className="re-reference">当前位置预览：<b>{relationName(reference)}</b> <small>{reference.planned?'计划':reference.evidence?'正文确认':'资料设定'}</small></p>}<label>变化后的关系<input required aria-label="变化后的关系" placeholder="例如：互相试探 → 决定合作" value={value.name} onChange={e=>set('name',e.target.value)}/></label><RelationshipTypePicker {...{call,novelId}} busy={unavailable||saving} value={value.typeId} onChange={(typeId,type)=>setValue(v=>({...v,typeId,name:type?.name||v.name}))}/><label>变化原因<GrowingTextarea aria-label="变化原因" placeholder="是什么让两人的关系发生改变？" value={value.reason} onChange={e=>set('reason',e.target.value)}/></label></section>
  <section className="re-section"><h4>02 <span>剧情与发生位置</span></h4><div className="u-form-grid"><label>关联剧情卡<select aria-label="关联剧情卡" value={value.cardId} onChange={e=>setValue(v=>({...v,cardId:e.target.value,pointId:''}))}>{cards.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><label>发生点<select aria-label="发生点" value={value.pointId} onChange={e=>set('pointId',e.target.value)}><option value="">独立发生点</option>{card?.points.filter(p=>p.relationships?.length).map(p=><option key={p.id} value={p.id}>{describe(p,sources.chapters)} · {p.relationships.length} 次变化</option>)}</select></label></div>
   {shared?<p className="re-help">追加到所选发生点，沿用它的位置；可在节点管理中调整同点顺序。</p>:<><div className="re-location-heading"><span>时间可暂不安排</span><button type="button" onClick={useCursor}>使用当前指针</button></div><div className="u-form-grid"><label>发生章节<select aria-label="发生章节" value={location.narration?.chapterId||''} onChange={e=>setLocation('narration',e.target.value?{chapterId:e.target.value,offset:location.narration?.offset||0}:null)}><option value="">叙述位置待定</option>{location.narration&&!sources.chapters.some(c=>c.id===location.narration.chapterId)&&<option value={location.narration.chapterId}>章节已移除 · 请重新选择</option>}{sources.chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label><label>章内位置（%）<input aria-label="章内位置" type="number" min="0" max="99.9" step="0.1" disabled={!location.narration} value={location.narration?Math.round(location.narration.offset*1000)/10:0} onChange={e=>setLocation('narration',{...location.narration,offset:Number(e.target.value)/100})}/></label><label>故事时间{state.storyAxis?<><select aria-label="关系故事时间定位方式" value={location.story?.binding?.kind==='card'?'bound':Number.isFinite(location.story)?'legacy':'pending'} onChange={async e=>{const next=e.target.value;if(next==='bound'){if(Number.isFinite(location.story)&&!await confirm('将旧固定坐标改为跟随剧情卡起点？原坐标不会自动换算为日期，叙述位置与正文依据保持不变。'))return;setLocation('story',{binding:{kind:'card',offset:0}});}else if(next==='pending')setLocation('story',null);}}><option value="bound">跟随剧情卡</option><option value="pending">故事时间待定</option>{Number.isFinite(location.story)&&<option value="legacy">旧固定坐标 · 未映射日期</option>}</select>{location.story?.binding?.kind==='card'?<><input aria-label="关系相对剧情卡的天数" type="number" step="1" value={location.story.binding.offset??0} onChange={e=>setLocation('story',{binding:{...location.story.binding,offset:Number(e.target.value)}})}/><small>相对剧情卡起点的天数；卡片未安排日期时保持待定。</small></>:Number.isFinite(location.story)?<small>原坐标 {location.story} 保留，不参与新历法排序。</small>:null}</>:<input aria-label="关系发生的故事时间" type="number" step="any" placeholder="待定" value={Number.isFinite(location.story)?location.story:''} onChange={e=>setLocation('story',e.target.value===''?null:Number(e.target.value))}/>}</label><label>同位置顺序<input aria-label="同位置顺序" type="number" min="0" step="1" value={value.order} onChange={e=>set('order',Number(e.target.value))}/></label></div>{targetPoint?.relationships.length>1&&<p className="re-help">此点包含 {targetPoint.relationships.length} 次变化，调整位置会一起移动；只移动这一条时，请选择“独立发生点”。</p>}</>}
  </section>
  <section className="re-section"><h4>03 <span>计划与正文依据</span></h4><div className="re-modes" role="group" aria-label="关系变化性质"><button type="button" aria-pressed={!value.fact} onClick={()=>set('fact',false)}>先做计划</button><button type="button" aria-pressed={value.fact} onClick={()=>set('fact',true)}>正文已发生</button></div>
   {value.fact?<div className="re-proof">{original?.evidence&&<div className="re-old-proof"><small>原确认依据 · 版本 {original.evidence.revision}{proofReview(original.evidence,sources.chapters)?' · 正文已改写，待复核':''}</small><blockquote>{original.evidence.evidence}</blockquote>{unchangedProof&&<button type="button" onClick={()=>set('reconfirm',true)}>用当前正文重新确认</button>}</div>}<label>依据章节<select aria-label="依据章节" value={value.chapterId} onChange={e=>setValue(v=>({...v,chapterId:e.target.value,quote:'',reconfirm:true}))}><option value="">选择已保存正文</option>{sources.chapters.map(c=><option key={c.id} value={c.id}>{c.title}</option>)}</select></label>{proof.error&&<p role="alert">{proof.error}<button type="button" onClick={proof.retry}>重新读取</button></p>}{current&&<details><summary>查看已保存正文 · 版本 {current.revision}</summary><pre>{current.content}</pre></details>}<label>引用原文<GrowingTextarea aria-label="引用原文" value={value.quote} onChange={e=>setValue(v=>({...v,quote:e.target.value,reconfirm:true}))}/></label>{!hasLocation&&<p className="re-help">确认正文前，请先指定发生章节或故事时间。</p>}{value.quote&&!unchangedProof&&!validQuote&&<p className="re-help">引用需完整匹配当前已保存正文。</p>}<small>保存即确认这条关系变化。后续正文改写会提示复核，旧依据会保留。</small></div>:<p className="re-help">只记录构思。安排时间、采用剧情卡，都不会自动变成正文事实。</p>}
  </section>{error&&<p className="re-error" role="alert">{error}</p>}<div className="u-form-footer"><button type="button" disabled={saving} onClick={discard}>取消</button><button className="u-primary" type="submit" disabled={unavailable||saving||invalid}>{saving?'保存中…':value.fact?'确认正文并保存':'保存计划'}</button></div>
 </form></Modal>;
}

function GrowingTextarea(props){const ref=useRef(null);useAutosizeTextarea(ref,props.value);return <textarea ref={ref} {...props}/>;}
